1	// Package data implements datasource registration and reading.
2	package data
3	
4	import (
5		"context"
6		"fmt"
7		"io"
8		"net/http"
9		"net/url"
10		"os"
11		"path/filepath"
12		"sort"
13		"strings"
14		"sync"
15	
16		"github.com/reimpl/gomplate/internal/dataparse"
17	)
18	
19	// Source is a single registered datasource.
20	type Source struct {
21		Alias  string
22		URL    *url.URL
23		Header http.Header
24	}
25	
26	// Registry holds all defined datasources.
27	type Registry struct {
28		mu       sync.Mutex
29		sources  map[string]*Source
30		headers  map[string]http.Header
31		stdin    io.Reader
32		stdinBuf []byte
33		client   *http.Client
34		cache    map[string]interface{}
35	}
36	
37	func NewRegistry(stdin io.Reader) *Registry {
38		return &Registry{
39			sources: map[string]*Source{},
40			headers: map[string]http.Header{},
41			stdin:   stdin,
42			client:  &http.Client{},
43			cache:   map[string]interface{}{},
44		}
45	}
46	
47	// Define parses a datasource definition of the form "alias=URL", "alias=",
48	// or a bare URL (alias inferred). Returns the alias.
49	func (r *Registry) Define(def string) (string, error) {
50		return r.DefineWithHeader(def, nil)
51	}
52	
53	func (r *Registry) DefineWithHeader(def string, header http.Header) (string, error) {
54		alias, rawurl, ok := strings.Cut(def, "=")
55		if !ok {
56			// no '=' - the whole thing is a URL; infer alias
57			rawurl = def
58			alias = ""
59		}
60		if alias == "" {
61			alias = inferAlias(rawurl)
62			if alias == "" {
63				return "", fmt.Errorf("could not infer datasource alias from %q", def)
64			}
65		}
66		u, err := parseSourceURL(rawurl)
67		if err != nil {
68			return "", fmt.Errorf("invalid datasource URL %q: %v", rawurl, err)
69		}
70		if old, dup := r.sources[alias]; dup {
71			_ = old
72			// later definitions override earlier ones
73		}
74		r.sources[alias] = &Source{Alias: alias, URL: u, Header: header}
75		return alias, nil
76	}
77	
78	// DefineURL defines a datasource from an already-split alias and URL string.
79	func (r *Registry) DefineURL(alias, rawurl string, header http.Header) error {
80		u, err := parseSourceURL(rawurl)
81		if err != nil {
82			return fmt.Errorf("invalid datasource URL %q: %v", rawurl, err)
83		}
84		r.sources[alias] = &Source{Alias: alias, URL: u, Header: header}
85		return nil
86	}
87	
88	func inferAlias(rawurl string) string {
89		// only for plain relative filenames in the current directory
90		if strings.ContainsAny(rawurl, "/:") {
91			return ""
92		}
93		base := filepath.Base(rawurl)
94		ext := filepath.Ext(base)
95		return strings.TrimSuffix(base, ext)
96	}
97	
98	func parseSourceURL(rawurl string) (*url.URL, error) {
99		if rawurl == "" {
100			return &url.URL{}, nil
101		}
102		u, err := url.Parse(rawurl)
103		if err != nil {
104			return nil, err
105		}
106		// bare relative paths (no scheme) are file URLs
107		if u.Scheme == "" {
108			u = &url.URL{Scheme: "file", Path: rawurl}
109			if strings.HasPrefix(rawurl, "/") {
110				u = &url.URL{Scheme: "file", Path: rawurl}
111			}
112		}
113		return u, nil
114	}
115	
116	// AddExtraHeader records headers to send for the given datasource alias.
117	func (r *Registry) AddExtraHeader(alias string, h http.Header) {
118		r.headers[alias] = h
119	}
120	
121	// Exists reports whether a datasource alias is defined.
122	func (r *Registry) Exists(alias string) bool {
123		_, ok := r.sources[alias]
124		return ok
125	}
126	
127	// Aliases returns sorted defined aliases.
128	func (r *Registry) Aliases() []string {
129		out := make([]string, 0, len(r.sources))
130		for a := range r.sources {
131			out = append(out, a)
132		}
133		sort.Strings(out)
134		return out
135	}
136	
137	// Get returns the source for an alias.
138	func (r *Registry) Get(alias string) (*Source, bool) {
139		s, ok := r.sources[alias]
140		return s, ok
141	}
142	
143	func (r *Registry) lookup(alias string) (*Source, error) {
144		r.mu.Lock()
145		defer r.mu.Unlock()
146		s, ok := r.sources[alias]
147		if !ok {
148			return nil, fmt.Errorf("undefined datasource '%s'", alias)
149		}
150		return s, nil
151	}
152	
153	// subPath appends extra path args to the source URL.
154	func subPath(u *url.URL, args ...string) *url.URL {
155		v := *u
156		if len(args) > 0 && args[0] != "" {
157			p := strings.Join(args, "/")
158			base := v.Path
159			if v.Opaque != "" {
160				base = v.Opaque
161			}
162			if strings.HasSuffix(base, "/") {
163				base += p
164			} else if base == "" {
165				base = p
166			} else {
167				base += "/" + p
168			}
169			if v.Opaque != "" {
170				v.Opaque = base
171			} else {
172				v.Path = base
173			}
174		}
175		return &v
176	}
177	
178	// Datasource reads and parses a datasource.
179	func (r *Registry) Datasource(ctx context.Context, alias string, args ...string) (interface{}, error) {
180		s, err := r.lookup(alias)
181		if err != nil {
182			return nil, err
183		}
184		u := subPath(s.URL, args...)
185		key := alias + "|" + u.String()
186		if v, ok := r.cache[key]; ok {
187			return v, nil
188		}
189		v, err := r.read(ctx, s, u, false)
190		if err != nil {
191			return nil, err
192		}
193		r.cache[key] = v
194		return v, nil
195	}
196	
197	// Include reads a datasource and returns raw string content.
198	func (r *Registry) Include(ctx context.Context, alias string, args ...string) (string, error) {
199		s, err := r.lookup(alias)
200		if err != nil {
201			return "", err
202		}
203		u := subPath(s.URL, args...)
204		v, err := r.read(ctx, s, u, true)
205		if err != nil {
206			return "", err
207		}
208		return v.(string), nil
209	}
210	
211	// read fetches content. If raw is true, returns the content as string.
212	func (r *Registry) read(ctx context.Context, s *Source, u *url.URL, raw bool) (interface{}, error) {
213		scheme := u.Scheme
214		switch scheme {
215		case "file", "":
216			return r.readFile(u, raw)
217		case "stdin":
218			return r.readStdin(u, raw)
219		case "env":
220			return r.readEnv(u, raw)
221		case "http", "https":
222			return r.readHTTP(ctx, s, u, raw)
223		case "merge":
224			return r.readMerge(ctx, s, u, raw)
225		default:
226			return nil, fmt.Errorf("datasources with scheme %q are not supported", scheme)
227		}
228	}
229	
230	func mimeOverride(u *url.URL) string {
231		param := os.Getenv("GOMPLATE_TYPE_PARAM")
232		if param == "" {
233			param = "type"
234		}
235		q := u.Query()
236		t := q.Get(param)
237		if i := strings.IndexByte(t, ';'); i >= 0 {
238			t = strings.TrimSpace(t[:i])
239		}
240		return t
241	}
242	
243	var extMimes = map[string]string{
244		".json": "application/json",
245		".yml":  "application/yaml",
246		".yaml": "application/yaml",
247		".toml": "application/toml",
248		".csv":  "text/csv",
249		".env":  "application/x-env",
250	}
251	
252	func mimeFor(u *url.URL, httpMime string) string {
253		if t := mimeOverride(u); t != "" {
254			return t
255		}
256		if httpMime != "" {
257			if i := strings.IndexByte(httpMime, ';'); i >= 0 {
258				httpMime = strings.TrimSpace(httpMime[:i])
259			}
260			if m, ok := extMimes[strings.ToLower(filepath.Ext(u.Path))]; ok && httpMime == "text/plain" {
261				return m
262			}
263			return httpMime
264		}
265		ext := strings.ToLower(filepath.Ext(u.Path))
266		if m, ok := extMimes[ext]; ok {
267			return m
268		}
269		return "text/plain"
270	}
271	
272	// parseContent parses bytes per MIME type.
273	func parseContent(mime string, b []byte) (interface{}, error) {
274		switch mime {
275		case "application/json":
276			return dataparse.JSON(b)
277		case "application/array+json":
278			return dataparse.JSONArray(b)
279		case "application/yaml", "application/x-yaml", "text/yaml":
280			if dataparse.YAML == nil {
281				return nil, fmt.Errorf("YAML support unavailable")
282			}
283			return dataparse.YAML(b)
284		case "application/toml":
285			if dataparse.TOML == nil {
286				return nil, fmt.Errorf("TOML support unavailable")
287			}
288			return dataparse.TOML(b)
289		case "text/csv":
290			return dataparse.CSV(0, b)
291		case "application/x-env":
292			return dataparse.EnvFile(b)
293		case "text/plain", "application/octet-stream", "":
294			return string(b), nil
295		default:
296			return nil, fmt.Errorf("unsupported MIME type: %s", mime)
297		}
298	}
299	
300	func (r *Registry) readFile(u *url.URL, raw bool) (interface{}, error) {
301		path := u.Path
302		if u.Host != "" && u.Host != "." {
303			path = u.Host + u.Path
304		}
305		if strings.HasSuffix(u.Path, "/") {
306			entries, err := os.ReadDir(path)
307			if err != nil {
308				return nil, err
309			}
310			names := []string{}
311			for _, e := range entries {
312				names = append(names, e.Name())
313			}
314			return names, nil
315		}
316		b, err := os.ReadFile(path)
317		if err != nil {
318			return nil, err
319		}
320		if raw {
321			return string(b), nil
322		}
323		return parseContent(mimeFor(u, ""), b)
324	}
325	
326	func (r *Registry) readStdin(u *url.URL, raw bool) (interface{}, error) {
327		r.mu.Lock()
328		if r.stdinBuf == nil {
329			b, err := io.ReadAll(r.stdin)
330			if err != nil {
331				r.mu.Unlock()
332				return nil, err
333			}
334			r.stdinBuf = b
335		}
336		b := r.stdinBuf
337		r.mu.Unlock()
338		if raw {
339			return string(b), nil
340		}
341		return parseContent(mimeFor(u, ""), b)
342	}
343	
344	func (r *Registry) readEnv(u *url.URL, raw bool) (interface{}, error) {
345		name := u.Opaque
346		if name == "" {
347			name = strings.TrimLeft(u.Path, "/")
348		}
349		val := os.Getenv(name)
350		if raw {
351			return val, nil
352		}
353		return parseContent(mimeFor(u, ""), []byte(val))
354	}
355	
356	func (r *Registry) readHTTP(ctx context.Context, s *Source, u *url.URL, raw bool) (interface{}, error) {
357		req, err := http.NewRequestWithContext(ctx, http.MethodGet, u.String(), nil)
358		if err != nil {
359			return nil, err
360		}
361		req.Header.Set("User-Agent", "Go-http-client/1.1")
362		for k, vs := range s.Header {
363			for _, v := range vs {
364				req.Header.Set(k, v)
365			}
366		}
367		if h, ok := r.headers[s.Alias]; ok {
368			for k, vs := range h {
369				for _, v := range vs {
370					req.Header.Set(k, v)
371				}
372			}
373		}
374		resp, err := r.client.Do(req)
375		if err != nil {
376			return nil, err
377		}
378		defer resp.Body.Close()
379		b, err := io.ReadAll(resp.Body)
380		if err != nil {
381			return nil, err
382		}
383		if resp.StatusCode < 200 || resp.StatusCode > 299 {
384			return nil, fmt.Errorf("unexpected HTTP status %d from %s", resp.StatusCode, u.String())
385		}
386		if raw {
387			return string(b), nil
388		}
389		return parseContent(mimeFor(u, resp.Header.Get("Content-Type")), b)
390	}
391	
392	func (r *Registry) readMerge(ctx context.Context, s *Source, u *url.URL, raw bool) (interface{}, error) {
393		parts := strings.Split(u.Opaque, "|")
394		if len(parts) < 2 {
395			return nil, fmt.Errorf("merge: requires at least two datasources")
396		}
397		var merged map[string]interface{}
398		// merge right to left
399		for i := len(parts) - 1; i >= 0; i-- {
400			p := parts[i]
401			var v interface{}
402			var err error
403			if r.Exists(p) {
404				v, err = r.Datasource(ctx, p)
405			} else {
406				tmp := &Source{Alias: p}
407				tu, terr := parseSourceURL(p)
408				if terr != nil {
409					return nil, terr
410				}
411				v, err = r.read(ctx, tmp, tu, false)
412			}
413			if err != nil {
414				return nil, err
415			}
416			m, ok := v.(map[string]interface{})
417			if !ok {
418				return nil, fmt.Errorf("merge: datasource %q is not a map", p)
419			}
420			merged = deepMerge(m, merged)
421		}
422		return merged, nil
423	}
424	
425	// deepMerge overlays src onto dst (src wins), merging nested maps.
426	func deepMerge(src, dst map[string]interface{}) map[string]interface{} {
427		if dst == nil {
428			dst = map[string]interface{}{}
429		}
430		for k, v := range src {
431			if sm, ok := v.(map[string]interface{}); ok {
432				if dm, ok := dst[k].(map[string]interface{}); ok {
433					dst[k] = deepMerge(sm, dm)
434					continue
435				}
436			}
437			dst[k] = v
438		}
439		return dst
440	}

