284	func (r *renderer) newTemplate(name string) *template.Template {
285		t := template.New(name)
286		t.Option("missingkey=" + r.cfg.MissingKey)
287		t.Delims(r.cfg.LeftDelim, r.cfg.RightDelim)
288		t.Funcs(r.funcMap())
