package funcs

import (
	"reflect"
	"testing"
)

func TestFilePathBase(t *testing.T) {
	fp := FilePath{}
	cases := []struct {
		in  interface{}
		out string
	}{
		{"/tmp/foo", "foo"},
		{"", "."},
		{"/", "/"},
		{42, "42"},
		{3.14, "3.14"},
		{4.0, "4"},
		{nil, "nil"},
		{`a\b`, `a\b`}, // backslash is not a separator on linux
	}
	for _, c := range cases {
		if got := fp.Base(c.in); got != c.out {
			t.Errorf("Base(%v) = %q, want %q", c.in, got, c.out)
		}
	}
}

func TestFilePathCleanDirExt(t *testing.T) {
	fp := FilePath{}
	if got := fp.Clean("/tmp//foo/../"); got != "/tmp" {
		t.Errorf("Clean = %q", got)
	}
	if got := fp.Dir("/tmp/foo"); got != "/tmp" {
		t.Errorf("Dir = %q", got)
	}
	if got := fp.Ext("/tmp/foo.csv"); got != ".csv" {
		t.Errorf("Ext = %q", got)
	}
}

func TestFilePathSlashFuncs(t *testing.T) {
	fp := FilePath{}
	if got := fp.FromSlash("a/b"); got != "a/b" {
		t.Errorf("FromSlash = %q", got)
	}
	if got := fp.ToSlash(`a\b`); got != `a\b` { // no-op on linux
		t.Errorf("ToSlash = %q", got)
	}
	if got := fp.VolumeName("C:/foo"); got != "" {
		t.Errorf("VolumeName = %q", got)
	}
}

func TestFilePathIsAbs(t *testing.T) {
	fp := FilePath{}
	if !fp.IsAbs("/tmp/foo.csv") {
		t.Error("IsAbs(/tmp/foo.csv) should be true")
	}
	if fp.IsAbs("../foo.csv") {
		t.Error("IsAbs(../foo.csv) should be false")
	}
	if fp.IsAbs("") {
		t.Error("IsAbs(\"\") should be false")
	}
}

func TestFilePathJoin(t *testing.T) {
	fp := FilePath{}
	if got := fp.Join("/tmp", "foo", "bar"); got != "/tmp/foo/bar" {
		t.Errorf("Join = %q", got)
	}
	if got := fp.Join("a", 1, true); got != "a/1/true" {
		t.Errorf("Join with non-strings = %q", got)
	}
	if got := fp.Join(); got != "" {
		t.Errorf("Join() = %q", got)
	}
	if got := fp.Join(nil, "a"); got != "nil/a" {
		t.Errorf("Join(nil, a) = %q", got)
	}
}

func TestFilePathMatch(t *testing.T) {
	fp := FilePath{}
	ok, err := fp.Match("*.csv", "foo.csv")
	if err != nil || !ok {
		t.Errorf("Match = %v, %v", ok, err)
	}
	ok, err = fp.Match("", "x")
	if err != nil || ok {
		t.Errorf("Match empty pattern = %v, %v", ok, err)
	}
	if _, err = fp.Match("[", "x"); err == nil || err.Error() != "syntax error in pattern" {
		t.Errorf("Match bad pattern err = %v", err)
	}
}

func TestFilePathRel(t *testing.T) {
	fp := FilePath{}
	got, err := fp.Rel("/a", "/a/b/c")
	if err != nil || got != "b/c" {
		t.Errorf("Rel = %q, %v", got, err)
	}
	if got, _ := fp.Rel("", ""); got != "." {
		t.Errorf("Rel(\"\", \"\") = %q", got)
	}
	if _, err := fp.Rel("a", "/b"); err == nil || err.Error() != "Rel: can't make /b relative to a" {
		t.Errorf("Rel err = %v", err)
	}
}

func TestFilePathSplit(t *testing.T) {
	fp := FilePath{}
	if got := fp.Split("/tmp/foo"); !reflect.DeepEqual(got, []string{"/tmp/", "foo"}) {
		t.Errorf("Split = %v", got)
	}
	if got := fp.Split(""); !reflect.DeepEqual(got, []string{"", ""}) {
		t.Errorf("Split(\"\") = %v", got)
	}
}

func TestPathFuncs(t *testing.T) {
	p := Path{}
	if got := p.Base("/tmp/foo"); got != "foo" {
		t.Errorf("Base = %q", got)
	}
	if got := p.Base(""); got != "." {
		t.Errorf("Base(\"\") = %q", got)
	}
	if got := p.Clean("/tmp//foo/../"); got != "/tmp" {
		t.Errorf("Clean = %q", got)
	}
	if got := p.Dir("/tmp/foo"); got != "/tmp" {
		t.Errorf("Dir = %q", got)
	}
	if got := p.Ext("/tmp/foo.csv"); got != ".csv" {
		t.Errorf("Ext = %q", got)
	}
	if !p.IsAbs("/a") || p.IsAbs("a") {
		t.Error("IsAbs wrong")
	}
	if got := p.Join("/tmp", "foo", "bar"); got != "/tmp/foo/bar" {
		t.Errorf("Join = %q", got)
	}
	if got := p.Join("a", 1, true); got != "a/1/true" {
		t.Errorf("Join non-strings = %q", got)
	}
	if got := p.Join(); got != "" {
		t.Errorf("Join() = %q", got)
	}
	ok, err := p.Match("*.csv", "foo.csv")
	if err != nil || !ok {
		t.Errorf("Match = %v, %v", ok, err)
	}
	if _, err := p.Match("[", "x"); err == nil || err.Error() != "syntax error in pattern" {
		t.Errorf("Match bad pattern err = %v", err)
	}
	if got := p.Split("/tmp/foo"); !reflect.DeepEqual(got, []string{"/tmp/", "foo"}) {
		t.Errorf("Split = %v", got)
	}
}

func TestPathArgToString(t *testing.T) {
	if got := pathArgToString(nil); got != "nil" {
		t.Errorf("nil -> %q", got)
	}
	if got := pathArgToString(1e21); got != "1e+21" {
		t.Errorf("1e21 -> %q", got)
	}
	if got := pathArgToString(map[string]interface{}{}); got != "map[]" {
		t.Errorf("empty map -> %q", got)
	}
}

